std::string clean(std::string word)
{
    // TODO: lower-case it, and remove punctuation from the start and the end
    return word;
}

int main()
{
    std::unordered_map<std::string, int> counts{};
    int lines{ 0 };
    std::string line{};
    while (std::getline(std::cin, line))
    {
        ++lines;
        std::istringstream words{ line };
        std::string word{};
        while (words >> word)
        {
            word = clean(word);
            if (!word.empty()) ++counts[word];
        }
    }

    std::cout << std::format("Unique: {}   Lines: {}\n", counts.size(), lines);
    // TODO: total words, the top 10, the longest word and the average length
    return 0;
}
